trx.console.register({
  name = "greet",
  aliases = { "hello", "hi" },
  run = function(args)
    if args == "" then
      return trx.console.Result.BAD_INVOCATION, "greet who?"
    end
    trx.console.log("hello " .. args)
  end,
})

trx.events.on_flip_effect(62, function(timer, item_num)
  trx.log.info("flipeffect 62 ran with timer " .. timer)
end)

